import { 
  FundingParams, 
  CalculationResult, 
  CalculationLevel 
} from '../../types';

export class FundingCalculator {
  /**
   * 计算资金费率反向策略
   * @param params 策略参数
   * @param currentPrice 当前价格（可选）
   * @param currentFundingRate 当前资金费率（可选）
   * @returns 计算结果
   */
  static calculate(
    params: FundingParams, 
    currentPrice?: number, 
    currentFundingRate?: number
  ): CalculationResult {
    const { fundingThreshold, leverageRatio, maxLevels, totalCapital, isLong } = params;

    // 验证参数
    if (Math.abs(fundingThreshold) > 1) {
      throw new Error('资金费率阈值必须在-1到1之间');
    }

    if (leverageRatio <= 0 || leverageRatio > 100) {
      throw new Error('杠杆倍数必须在0-100之间');
    }

    if (maxLevels <= 0) {
      throw new Error('最大档数必须大于0');
    }

    if (totalCapital <= 0) {
      throw new Error('总本金必须大于0');
    }

    // 假设起始价格
    const basePrice = currentPrice || 50000;

    // 计算每档投入金额（平均分配）
    const amountPerLevel = totalCapital / maxLevels;

    const levels: CalculationLevel[] = [];
    let totalInvested = 0;
    let totalHoldings = 0;

    // 检查资金费率条件
    let fundingConditionMet = false;
    if (currentFundingRate !== undefined) {
      if (isLong) {
        // 做多：当资金费率为负时（空头支付多头）
        fundingConditionMet = currentFundingRate < fundingThreshold;
      } else {
        // 做空：当资金费率为正时（多头支付空头）
        fundingConditionMet = currentFundingRate > fundingThreshold;
      }
    }

    // 计算每个档位
    for (let i = 1; i <= maxLevels; i++) {
      // 根据做多做空方向计算触发价格
      let triggerPrice: number;
      if (isLong) {
        // 做多：价格下跌时加仓
        const priceStep = 5; // 每档5%跌幅
        triggerPrice = basePrice * (1 - (i * priceStep) / 100);
      } else {
        // 做空：价格上涨时加仓
        const priceStep = 5; // 每档5%涨幅
        triggerPrice = basePrice * (1 + (i * priceStep) / 100);
      }

      const investAmount = amountPerLevel;
      // 考虑杠杆的实际持仓量
      const leveragedAmount = investAmount * leverageRatio;
      const holdings = leveragedAmount / triggerPrice;

      // 判断是否已触发
      let triggered = false;
      if (currentPrice && currentFundingRate !== undefined) {
        const priceCondition = isLong ? 
          currentPrice <= triggerPrice : 
          currentPrice >= triggerPrice;

        // 第一档需要同时满足资金费率和价格条件
        if (i === 1) {
          triggered = fundingConditionMet && priceCondition;
        } else {
          // 后续档位：需要第一档已触发且价格条件满足
          const firstLevelTriggered = levels.length > 0 && levels[0].triggered;
          triggered = firstLevelTriggered && priceCondition;
        }
      }

      if (triggered) {
        totalInvested += investAmount;
        totalHoldings += holdings;
      }

      const level: CalculationLevel = {
        level: i,
        triggerPrice,
        investAmount,
        holdings,
        cumulativeInvested: triggered ? totalInvested : 0,
        cumulativeHoldings: triggered ? totalHoldings : 0,
        averageCost: triggered && totalHoldings > 0 ? totalInvested / totalHoldings : 0,
        triggered,
        // 添加杠杆相关信息
        leverageRatio,
        leveragedAmount
      };

      levels.push(level);
    }

    // 计算平均成本
    const averagePrice = totalHoldings > 0 ? totalInvested / totalHoldings : 0;
    const remainingCash = totalCapital - totalInvested;

    // 计算未实现盈亏（考虑杠杆）
    let unrealizedPnL = 0;
    let maxDrawdown = 0;
    let fundingPnL = 0;

    if (currentPrice && totalHoldings > 0) {
      // 计算价格变动盈亏
      const currentValue = totalHoldings * currentPrice;
      const costValue = totalHoldings * averagePrice;

      if (isLong) {
        unrealizedPnL = currentValue - costValue;
      } else {
        unrealizedPnL = costValue - currentValue; // 做空时价格下跌为盈利
      }

      // 计算资金费率收益（简化计算）
      if (currentFundingRate !== undefined) {
        const leveragedPosition = totalInvested * leverageRatio;
        fundingPnL = leveragedPosition * Math.abs(currentFundingRate) * 0.1; // 假设持有0.1天
      }

      // 总盈亏 = 价格盈亏 + 资金费率收益
      unrealizedPnL += fundingPnL;

      // 计算最大回撤
      if (totalInvested > 0) {
        maxDrawdown = Math.min(0, unrealizedPnL / totalInvested);
      }
    }

    const result: CalculationResult = {
      id: `calc_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      strategyId: params.id,
      strategyName: params.name,
      strategyType: params.type,
      calculatedAt: new Date(),
      levels,
      totalInvested,
      averagePrice,
      totalHoldings,
      remainingCapital: remainingCash,
      currentPriceAnalysis: currentPrice && totalHoldings > 0 ? {
        currentPrice,
        unrealizedPnL,
        unrealizedPnLPercentage: totalInvested > 0 ? unrealizedPnL / totalInvested : 0
      } : undefined,
      maxDrawdown,
      // 添加资金费率相关信息
      currentFundingRate,
      fundingPnL,
      leverageRatio
    };

    return result;
  }

  /**
   * 获取资金费率策略状态
   * @param params 策略参数
   * @param currentFundingRate 当前资金费率
   * @returns 策略状态信息
   */
  static getStrategyStatus(params: FundingParams, currentFundingRate: number) {
    const { fundingThreshold, isLong } = params;

    let conditionMet = false;
    let distance = 0;

    if (isLong) {
      conditionMet = currentFundingRate < fundingThreshold;
      distance = Math.abs(currentFundingRate - fundingThreshold);
    } else {
      conditionMet = currentFundingRate > fundingThreshold;
      distance = Math.abs(currentFundingRate - fundingThreshold);
    }

    let status: 'waiting' | 'ready' | 'active' | 'extreme';
    let message: string;

    const absRate = Math.abs(currentFundingRate);

    if (absRate > 0.01) { // 1%以上
      status = 'extreme';
      message = '资金费率极端，注意风险控制';
    } else if (conditionMet) {
      status = 'ready';
      message = isLong ? '负费率，适合做多收取费用' : '正费率，适合做空收取费用';
    } else {
      status = 'waiting';
      message = `等待${isLong ? '负' : '正'}费率信号`;
    }

    return {
      status,
      message,
      conditionMet,
      distance,
      fundingLevel: this.getFundingLevel(currentFundingRate),
      direction: isLong ? '做多' : '做空'
    };
  }

  /**
   * 获取资金费率水平描述
   * @param rate 资金费率
   * @returns 费率水平描述
   */
  private static getFundingLevel(rate: number): string {
    const absRate = Math.abs(rate);

    if (absRate >= 0.01) return '极端';
    if (absRate >= 0.005) return '很高';
    if (absRate >= 0.002) return '较高';
    if (absRate >= 0.001) return '正常';
    return '很低';
  }

  /**
   * 计算资金费率收益预期
   * @param params 策略参数
   * @param fundingRate 资金费率
   * @param days 持有天数
   * @returns 收益预期
   */
  static calculateFundingReturn(params: FundingParams, fundingRate: number, days: number = 1) {
    const { totalCapital, leverageRatio } = params;

    // 每天3次资金费率结算
    const settlementsPerDay = 3;
    const totalSettlements = days * settlementsPerDay;

    // 杠杆后的仓位价值
    const leveragedPosition = totalCapital * leverageRatio;

    // 资金费率收益（每次结算）
    const fundingPerSettlement = leveragedPosition * Math.abs(fundingRate);
    const totalFundingReturn = fundingPerSettlement * totalSettlements;

    // 年化收益率
    const annualizedReturn = (totalFundingReturn / totalCapital) * (365 / days);

    return {
      dailyReturn: fundingPerSettlement * settlementsPerDay,
      totalReturn: totalFundingReturn,
      returnRate: totalFundingReturn / totalCapital,
      annualizedReturn
    };
  }

  /**
   * 生成策略建议
   * @param params 策略参数
   * @param currentFundingRate 当前资金费率
   * @returns 建议列表
   */
  static generateRecommendations(params: FundingParams, currentFundingRate: number): string[] {
    const recommendations: string[] = [];
    const { leverageRatio, isLong, fundingThreshold } = params;

    const status = this.getStrategyStatus(params, currentFundingRate);

    // 资金费率状态建议
    if (status.status === 'extreme') {
      recommendations.push('⚠️ 资金费率极端，虽然收益高但风险也大');
      recommendations.push('💡 建议降低杠杆倍数或减少仓位');
    } else if (status.status === 'ready') {
      recommendations.push('✅ 资金费率条件满足，可以开始执行策略');
      recommendations.push(`📋 当前${status.direction}方向有利，注意价格变动风险`);
    } else {
      recommendations.push(`📊 等待${isLong ? '负' : '正'}费率信号，当前费率${(currentFundingRate * 100).toFixed(3)}%`);
    }

    // 杠杆建议
    if (leverageRatio > 10) {
      recommendations.push('⚠️ 杠杆倍数较高，注意爆仓风险');
      recommendations.push('💰 建议设置止损，控制最大损失');
    } else if (leverageRatio < 3) {
      recommendations.push('📈 杠杆倍数较低，资金费率收益有限');
    }

    // 阈值建议
    const absThreshold = Math.abs(fundingThreshold);
    if (absThreshold < 0.001) {
      recommendations.push('🎯 费率阈值较低，触发频率可能较高');
    } else if (absThreshold > 0.005) {
      recommendations.push('⏰ 费率阈值较高，需要等待极端市场情况');
    }

    // 通用建议
    recommendations.push('📊 密切关注资金费率变化，及时调整策略');
    recommendations.push('⚖️ 平衡资金费率收益与价格变动风险');

    return recommendations;
  }

  /**
   * 验证策略参数
   * @param params 策略参数
   * @returns 验证结果
   */
  static validateParams(params: Partial<FundingParams>): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    if (params.fundingThreshold === undefined || Math.abs(params.fundingThreshold) > 1) {
      errors.push('资金费率阈值必须在-1到1之间');
    }

    if (!params.leverageRatio || params.leverageRatio <= 0 || params.leverageRatio > 100) {
      errors.push('杠杆倍数必须在0-100之间');
    }

    if (!params.maxLevels || params.maxLevels <= 0 || params.maxLevels > 20) {
      errors.push('最大档数必须在1-20之间');
    }

    if (!params.totalCapital || params.totalCapital <= 0) {
      errors.push('总本金必须大于0');
    }

    if (params.isLong === undefined) {
      errors.push('必须选择做多或做空方向');
    }

    // 风险检查
    if (params.leverageRatio && params.leverageRatio > 20) {
      errors.push('杠杆倍数过高，存在爆仓风险');
    }

    if (params.fundingThreshold !== undefined && Math.abs(params.fundingThreshold) < 0.0001) {
      errors.push('费率阈值过小，可能导致频繁交易');
    }

    return {
      valid: errors.length === 0,
      errors
    };
  }
}
